def re_arrange_array(arr, n):
    if n <= 0:
        return arr
    j = 0
    for i in range(n):
        if arr[i] < 0:
            if i != j:
                # Shift elements to preserve relative order
                temp = arr[i]
                for k in range(i, j, -1):
                    arr[k] = arr[k - 1]
                arr[j] = temp
            j += 1
    return arr
